/*
 * This file was generated by the Gradle 'init' task.
 */

plugins {
    alias(libs.plugins.boot.application)
    `java-library`
    `maven-publish`
    checkstyle
    pmd
    alias(libs.plugins.spotless)
    alias(libs.plugins.spotbugs)
    alias(libs.plugins.jooq.codegen)
}

repositories {
    mavenLocal()
    maven {
        url = uri("https://repo.maven.apache.org/maven2/")
    }
}

dependencies {
    api(libs.org.jooq.jooq)

    jooqCodegen(libs.org.jooq.meta.extensions)

    api(libs.org.springframework.boot.spring.boot.starter.data.redis)
    api(libs.org.jspecify.jspecify)
    implementation(project(":payguard-shared"))
    testImplementation(libs.org.springframework.boot.spring.boot.starter.jooq.test)
    testImplementation(libs.com.redis.testcontainers.redis)
}

val spotbugsAnnotations = configurations.detachedConfiguration(libs.jetbrains.annotations.get())
tasks.withType<com.github.spotbugs.snom.SpotBugsTask>().configureEach {
    auxClassPaths.from(spotbugsAnnotations)
}

group = "dev.amg.payguard"
version = "1.0.0-SNAPSHOT"
description = "PayGuard Identity Service"
java.sourceCompatibility = JavaVersion.VERSION_25



tasks.withType<JavaCompile>() {
    options.encoding = "UTF-8"
}

tasks.withType<Javadoc>() {
    options.encoding = "UTF-8"
}

jooq {
    configuration {
        generator {
            database {
                name = "org.jooq.meta.extensions.ddl.DDLDatabase"
                properties {
                    property {
                        key = "scripts"
                        value = "${projectDir}/src/main/resources/db/jooq/*.sql"
                    }
                    property {
                        key = "sort"
                        value = "flyway"
                    }
                    property {
                        key = "defaultNameCase"
                        value = "lower"
                    }
                }
                schemata {
                    schema {
                        inputSchema = "PUBLIC"
                        outputSchema = "payguard"
                    }
                }
            }
            target {
                packageName = "dev.amg.payguard.identity.infrastructure.adapter.out.persistence.jooq.generated"
                // Refresh the existing checked-in package without creating duplicate classes.
                directory = "src/main/java"
            }
        }
    }
}

tasks.named<org.jooq.codegen.gradle.CodegenTask>("jooqCodegen") {
    inputs.files(fileTree("src/main/resources/db/jooq") { include("*.sql") })
    // The output shares src/main/java with handwritten sources; never restore it from cache.
    outputs.cacheIf { false }
}

tasks.register("generateJooq") {
    group = "code generation"
    description = "Regenerates jOOQ sources from the Identity SQL snapshots."
    dependsOn(tasks.named("jooqCodegen"))
}
